# tandem repeats, periods 2-12, find longest runs
def tandems(seq, minunit=2, maxunit=12, mincopies=3):
    found=[]
    i=0
    n=len(seq)
    while i < n:
        best=None
        for u in range(minunit, maxunit+1):
            unit=seq[i:i+u]
            if len(unit)<u: break
            c=1
            while seq[i+c*u:i+(c+1)*u]==unit:
                c+=1
            if c>=mincopies:
                if best is None or c*u>best[1]:
                    best=(u,c)
        if best:
            u,c=best
            found.append((i+1, i+c*u, u, c, seq[i:i+u]))
            i+=c*u
        else:
            i+=1
    return found

