seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
n=len(seq)

def maximal_repeats(seq,K,minlen):
    from collections import defaultdict
    idx=defaultdict(list)
    for i in range(len(seq)-K+1):
        idx[seq[i:i+K]].append(i)
    out=set()
    for k,pos in idx.items():
        if len(pos)<2: continue
        for x in range(len(pos)):
            for y in range(x+1,len(pos)):
                a,b=pos[x],pos[y]
                # extend
                while a>0 and b>0 and seq[a-1]==seq[b-1]:
                    a-=1;b-=1
                L=0
                while b+L<len(seq) and seq[a+L]==seq[b+L]:
                    L+=1
                if L>=minlen:
                    out.add((a,b,L))
    return sorted(out)

